// Call this inside a server function, never in next.config or middleware.
// BACKEND_URL is generated by Vercel and must not be set in environment files.
export function backendUrl(path, environment = process.env) {
  const binding = environment.BACKEND_URL;
  if (!binding && environment.VERCEL === '1') {
    throw new Error('The frontend service is missing its BACKEND_URL binding to backend.');
  }
  const base = binding || environment.API_INTERNAL_URL || 'http://127.0.0.1:4000';
  // Preserve a binding URL's path prefix and the backend's /api/v1 mount.
  return new URL(`api/v1${path}`, base.endsWith('/') ? base : `${base}/`);
}
